code.SafeMath.add(uint256,uint256):
function add(uint256 a, uint256 b) internal constant returns (uint256) {
 uint256 c = a + b;
 assert(c >= a);
 return c;
 }

code.SafeMath.mul(uint256,uint256):
function mul(uint256 a, uint256 b) internal constant returns (uint256) {
 uint256 c = a * b;
 assert(a == 0 || c / a == b);
 return c;
 }

code.Ownable.transferOwnership(address):
function transferOwnership(address newOwner) onlyOwner {
 require(newOwner != address(0));
 owner = newOwner;
 }

code.Crowdsale.goalReached():
function goalReached() constant returns (bool) {
 return (raisedAmount >= CAP * 1 ether);
 }

code.Crowdsale.tokensAvailable():
function tokensAvailable() constant returns (uint256) {
 return token.balanceOf(this);
 }

code.Crowdsale.initialize():
function initialize() onlyOwner {
 require(initialized == false);
 require(tokensAvailable() == initialTokens);
 initialized = true;
 }

code.Crowdsale.isActive():
function isActive() constant returns (bool) {
 return (
 initialized == true &&
 now >= START &&
 now <= START.add(DAYS * 1 days) &&
 goalReached() == false
 );
 }

code.Crowdsale.destroy():
function destroy() onlyOwner {
 uint256 balance = token.balanceOf(this);
 assert(balance > 0);
 token.transfer(owner, balance);
 selfdestruct(owner);
 }

code.Crowdsale.buyTokens():
function buyTokens() payable whenSaleIsActive {
 uint256 weiAmount = msg.value;
 uint256 tokens = weiAmount.mul(RATE);
 BoughtTokens(msg.sender, tokens);
 raisedAmount = raisedAmount.add(msg.value);
 token.transfer(msg.sender, tokens);
 owner.transfer(msg.value);
 }
